import { sameJson, type Json } from "./json.js";
import type { Child, Node } from "./tree.js";

/** Where a node is: the index of each child taken from the root down. */
export type Path = readonly number[];

/**
 * One change to a tree.
 *
 * Positional: a child is matched by its index, so a list that grows at the
 * end costs one `insert`, and one that changes in the middle costs the
 * children past the change. Patches apply in order, each to the tree the one
 * before it left.
 */
export type Patch =
  | { readonly op: "replace"; readonly path: Path; readonly node: Child }
  | { readonly op: "props"; readonly path: Path; readonly props: Node["props"] }
  | { readonly op: "insert"; readonly path: Path; readonly index: number; readonly node: Child }
  | { readonly op: "remove"; readonly path: Path; readonly index: number };

/** What changed from one tree to the next, so a renderer is sent that rather than the window again. */
export function diff(before: Child, after: Child, path: Path = []): Patch[] {
  if (typeof before === "string" || typeof after === "string" || before.type !== after.type) {
    return before === after ? [] : [{ op: "replace", path, node: after }];
  }

  const patches: Patch[] = sameJson(before.props, after.props) ? [] : [{ op: "props", path, props: after.props }];
  const shared = Math.min(before.children.length, after.children.length);
  for (let i = 0; i < shared; i++) {
    patches.push(...diff(before.children[i] as Child, after.children[i] as Child, [...path, i]));
  }
  for (let i = shared; i < after.children.length; i++) {
    patches.push({ op: "insert", path, index: i, node: after.children[i] as Child });
  }
  for (let i = before.children.length - 1; i >= shared; i--) patches.push({ op: "remove", path, index: i });
  return patches;
}

function nodeAt(tree: Child, path: Path): Node {
  if (typeof tree === "string") throw new TypeError(`no node at ${JSON.stringify(path)}: text holds no children`);
  return tree;
}

/** Whether `index` names a place among `length` slots; `end` allows the slot just past the last, where an insert appends. */
function within(index: number, length: number, end = false): boolean {
  return Number.isInteger(index) && index >= 0 && (end ? index <= length : index < length);
}

/** The tree with the node at `path` replaced by what `change` makes of it, every other node shared. */
function rewrite(tree: Child, path: Path, change: (node: Child) => Child): Child {
  if (path.length === 0) return change(tree);
  const node = nodeAt(tree, path);
  const [head, ...rest] = path as [number, ...number[]];
  if (!within(head, node.children.length)) throw new TypeError(`no child ${head} under ${node.type}`);
  const children = node.children.map((child, i) => (i === head ? rewrite(child, rest, change) : child));
  return { ...node, children };
}

function applyOne(tree: Child, patch: Patch): Child {
  switch (patch.op) {
    case "replace":
      return rewrite(tree, patch.path, () => patch.node);
    case "props":
      return rewrite(tree, patch.path, (node) => ({ ...nodeAt(node, patch.path), props: patch.props as { readonly [key: string]: Json } }));
    case "insert":
      return rewrite(tree, patch.path, (node) => {
        const target = nodeAt(node, patch.path);
        if (!within(patch.index, target.children.length, true)) throw new TypeError(`no place ${patch.index} to insert under ${target.type}`);
        return { ...target, children: [...target.children.slice(0, patch.index), patch.node, ...target.children.slice(patch.index)] };
      });
    case "remove":
      return rewrite(tree, patch.path, (node) => {
        const target = nodeAt(node, patch.path);
        if (!within(patch.index, target.children.length)) throw new TypeError(`no child ${patch.index} to remove under ${target.type}`);
        return { ...target, children: target.children.filter((_, i) => i !== patch.index) };
      });
  }
}

/**
 * The tree the patches describe, built from the one they were taken against.
 * The tree passed in is not changed. A patch naming a place the tree does not
 * have is refused rather than skipped: a renderer that quietly kept the old
 * tree would draw a window nobody sent it.
 */
export function patch(tree: Child, patches: readonly Patch[]): Child {
  return patches.reduce(applyOne, tree);
}

import { PRIMITIVES, type Primitive } from "../vocabulary.js";

/**
 * Where a region sits, said relationally: never a pixel and never a cell, so a
 * desktop window and a terminal are measured the same way.
 */
export type Place = "left" | "top" | "below" | "right" | "overlay";

export interface Region {
  readonly name: string;
  readonly place: Place;
  /** The region this one is placed relative to; `right-column` is everything not placed `left`. */
  readonly of?: string;
  readonly fullHeight: boolean;
  /** Drawn only while toggled on. */
  readonly toggled: boolean;
  /** An overlay, drawn only while open. */
  readonly openedBy?: string;
  readonly holds: readonly string[];
}

export interface Slot {
  readonly name: string;
  readonly fixed: readonly string[];
  /** The plugin collection that adds to it. */
  readonly extendedBy: string;
}

export interface Surface {
  readonly name: string;
  /** The primitives it may draw, or every one. */
  readonly holds: readonly Primitive[];
}

export interface Size {
  readonly width: number;
  readonly height: number;
}

export type Mode = "normal" | "insert";

export interface Frame {
  readonly version: 1;
  /** In the order the file declares them, which is the order a projection lists them in. */
  readonly regions: readonly Region[];
  readonly sections: { readonly fixed: readonly string[]; readonly extendedBy: string };
  readonly actions: readonly string[];
  readonly keys: { readonly normal: Readonly<Record<string, string>>; readonly insert: Readonly<Record<string, string>>; readonly leader: string };
  /** Gesture, then what it lands on, then the action. */
  readonly mouse: Readonly<Record<string, Readonly<Record<string, string>>>>;
  readonly surfaces: readonly Surface[];
  readonly slots: readonly Slot[];
  readonly narrowest: { readonly cells: Size; readonly px: Size };
  readonly abbreviate: { readonly marker: string; readonly keeps: number };
}

const PLACES: readonly Place[] = ["left", "top", "below", "right", "overlay"];

function refuse(at: string, said: string): never {
  throw new TypeError(`frame.yaml: ${at} ${said}`);
}

type Data = Readonly<Record<string, unknown>>;

const isData = (value: unknown): value is Data => typeof value === "object" && value !== null && !Array.isArray(value);

function data(value: unknown, at: string): Data {
  return isData(value) ? value : refuse(at, "is not a mapping");
}

function strings(value: unknown, at: string): readonly string[] {
  if (!Array.isArray(value) || !value.every((item) => typeof item === "string")) refuse(at, "is not a list of names");
  return value as string[];
}

function text(value: unknown, at: string): string {
  return typeof value === "string" && value !== "" ? value : refuse(at, "is not a name");
}

function count(value: unknown, at: string): number {
  return typeof value === "number" && Number.isInteger(value) && value > 0 ? value : refuse(at, "is not a positive whole number");
}

function onlyKeys(value: Data, allowed: readonly string[], at: string): void {
  const extra = Object.keys(value).filter((key) => !allowed.includes(key));
  if (extra.length > 0) refuse(at, `has ${extra.map((key) => `\`${key}\``).join(", ")}, which the frame does not declare`);
}

function region(name: string, value: unknown): Region {
  const at = `regions.${name}`;
  const spec = data(value, at);
  onlyKeys(spec, ["place", "of", "spans", "toggled", "opened-by", "holds"], at);
  const place = spec.place;
  if (typeof place !== "string" || !(PLACES as readonly string[]).includes(place)) refuse(`${at}.place`, `is not one of ${PLACES.join(", ")}`);
  if (spec.spans !== undefined && spec.spans !== "full-height") refuse(`${at}.spans`, "can only be full-height");
  if (spec.toggled !== undefined && typeof spec.toggled !== "boolean") refuse(`${at}.toggled`, "is not true or false");
  return {
    name,
    place: place as Place,
    ...(spec.of === undefined ? {} : { of: text(spec.of, `${at}.of`) }),
    fullHeight: spec.spans === "full-height",
    toggled: spec.toggled === true,
    ...(spec["opened-by"] === undefined ? {} : { openedBy: text(spec["opened-by"], `${at}.opened-by`) }),
    holds: strings(spec.holds, `${at}.holds`),
  };
}

function checkPlacements(regions: readonly Region[]): void {
  const names = regions.map((each) => each.name);
  for (const each of regions) {
    if (each.of !== undefined && each.of !== "right-column" && !names.includes(each.of)) {
      refuse(`regions.${each.name}.of`, `names ${each.of}, which is not a region`);
    }
    if (each.place !== "left" && each.place !== "overlay" && each.of === undefined) refuse(`regions.${each.name}`, `is ${each.place} of nothing`);
  }
}

function keymap(value: unknown, actions: readonly string[], at: string): Readonly<Record<string, string>> {
  const map = data(value, at);
  for (const [key, action] of Object.entries(map)) {
    if (typeof action !== "string" || !actions.includes(action)) refuse(`${at}.${key}`, `is bound to ${String(action)}, which is not a declared action`);
  }
  return map as Record<string, string>;
}

function mouse(value: unknown, actions: readonly string[]): Frame["mouse"] {
  return Object.fromEntries(Object.entries(data(value, "mouse")).map(([gesture, targets]) => [gesture, keymap(targets, actions, `mouse.${gesture}`)]));
}

function surface(name: string, value: unknown): Surface {
  const at = `surfaces.${name}`;
  const spec = data(value, at);
  onlyKeys(spec, ["holds"], at);
  if (spec.holds === "all") return { name, holds: PRIMITIVES };
  const holds = strings(spec.holds, `${at}.holds`);
  const unknown = holds.find((each) => !(PRIMITIVES as readonly string[]).includes(each));
  if (unknown !== undefined) refuse(`${at}.holds`, `names ${unknown}, which is not a primitive`);
  return { name, holds: holds as Primitive[] };
}

function slot(name: string, value: unknown): Slot {
  const at = `slots.${name}`;
  const spec = data(value, at);
  onlyKeys(spec, ["fixed", "extended-by"], at);
  return { name, fixed: spec.fixed === undefined ? [] : strings(spec.fixed, `${at}.fixed`), extendedBy: text(spec["extended-by"], `${at}.extended-by`) };
}

function size(value: unknown, at: string): Size {
  const spec = data(value, at);
  onlyKeys(spec, ["width", "height"], at);
  return { width: count(spec.width, `${at}.width`), height: count(spec.height, `${at}.height`) };
}

const TOP_LEVEL = ["version", "regions", "sections", "actions", "keys", "mouse", "surfaces", "slots", "narrowest", "abbreviate"];

/**
 * The frame, checked from what `frame.yaml` parses to: a placement relative to
 * a region that does not exist, a key bound to an action the frame does not
 * declare, or a key the file does not know is refused by name.
 *
 * It takes data rather than text so this package parses no YAML: whoever
 * reads the file — the conformance harness, the server — hands it here.
 */
export function checkFrame(value: unknown): Frame {
  const root = data(value, "the file");
  onlyKeys(root, TOP_LEVEL, "the file");
  if (root.version !== 1) refuse("version", "is not 1");
  const regions = Object.entries(data(root.regions, "regions")).map(([name, spec]) => region(name, spec));
  checkPlacements(regions);
  const sections = data(root.sections, "sections");
  const actions = strings(root.actions, "actions");
  const keys = data(root.keys, "keys");
  onlyKeys(keys, ["normal", "insert", "leader"], "keys");
  const narrowest = data(root.narrowest, "narrowest");
  const abbreviate = data(root.abbreviate, "abbreviate");
  return {
    version: 1,
    regions,
    sections: { fixed: strings(sections.fixed, "sections.fixed"), extendedBy: text(sections["extended-by"], "sections.extended-by") },
    actions,
    keys: {
      normal: keymap(keys.normal, actions, "keys.normal"),
      insert: keymap(keys.insert, actions, "keys.insert"),
      leader: text(keys.leader, "keys.leader"),
    },
    mouse: mouse(root.mouse, actions),
    surfaces: Object.entries(data(root.surfaces, "surfaces")).map(([name, spec]) => surface(name, spec)),
    slots: Object.entries(data(root.slots, "slots")).map(([name, spec]) => slot(name, spec)),
    narrowest: { cells: size(narrowest.cells, "narrowest.cells"), px: size(narrowest.px, "narrowest.px") },
    abbreviate: { marker: text(abbreviate.marker, "abbreviate.marker"), keeps: count(abbreviate.keeps, "abbreviate.keeps") },
  };
}

/**
 * Whether `shown` is `full`, or `full` shortened the one way the frame allows:
 * its first characters, at least `keeps` of them, followed by the marker.
 */
export function abbreviates(frame: Frame, shown: string, full: string): boolean {
  if (shown === full) return true;
  const { marker, keeps } = frame.abbreviate;
  if (!shown.endsWith(marker)) return false;
  const kept = shown.slice(0, -marker.length);
  return kept.length >= keeps && kept.length < full.length && full.startsWith(kept);
}

export { abbreviates, checkFrame, type Frame, type Mode, type Place, type Region, type Size, type Slot, type Surface } from "./frame.js";
export { buildKeymap, KeyReader, keysFor, parseKeys, type KeyOverrides, type Keymap, type KeyResult } from "./keymap.js";
export type { Box, ConformanceRenderer, Laid, LaidRegion, LaidSurface, Pointer, Scene, Session, Unit } from "./renderer.js";

import type { Frame, Mode } from "./frame.js";

/**
 * Keys in Neovim's own notation (`:help key-notation`): a printable key is
 * itself, a special one is named between angle brackets — `<CR>`, `<Esc>`,
 * `<Space>`, `<C-k>` — and `<leader>` is whatever the leader is.
 */
const SPECIAL: Readonly<Record<string, string>> = {
  cr: "CR",
  return: "CR",
  enter: "CR",
  esc: "Esc",
  space: "Space",
  tab: "Tab",
  bs: "BS",
  del: "Del",
  up: "Up",
  down: "Down",
  left: "Left",
  right: "Right",
  home: "Home",
  end: "End",
  pageup: "PageUp",
  pagedown: "PageDown",
  // Printable keys with a name: alone, each is its own character, so `<Bar>` and `|` are one key.
  bar: "|",
  bslash: "\\",
};

/** Printable characters that are named keys: a literal space is the same key as `<Space>`. */
const LITERAL: Readonly<Record<string, string>> = { " ": "<Space>", "\t": "<Tab>" };

/** Modifiers in the order a canonical key spells them. `D` is the command key. */
const MODIFIERS = ["C", "M", "S", "D"] as const;
const ALIASES: Readonly<Record<string, (typeof MODIFIERS)[number]>> = { c: "C", m: "M", a: "M", s: "S", d: "D" };

function refuse(at: string, said: string): never {
  throw new TypeError(`${at}: ${said}`);
}

/** The base of a bracketed key, `k` of `<C-k>` or `CR` of `<C-CR>`. */
function base(name: string, at: string): string {
  if (name.length === 1) return name;
  const special = SPECIAL[name.toLowerCase()];
  return special ?? refuse(at, `<${name}> is not a key Neovim names`);
}

/** A key and its modifiers, spelled the one way Neovim would read them back. */
function canonical(modifiers: ReadonlySet<string>, key: string): string {
  // Neovim reads <C-K> as <C-k>: under Control a letter has no case. <M-a> and <M-A> stay two keys.
  const name = modifiers.has("C") && key.length === 1 ? key.toLowerCase() : key;
  if (modifiers.size === 0) return name.length === 1 ? name : `<${name}>`;
  // Shift alone on a letter is the capital letter: `<S-g>` is `G`.
  if (modifiers.size === 1 && modifiers.has("S") && /^[a-zA-Z]$/.test(name)) return name.toUpperCase();
  return `<${MODIFIERS.filter((each) => modifiers.has(each)).map((each) => `${each}-`).join("")}${name}>`;
}

function bracketed(inside: string, at: string): string {
  if (inside.toLowerCase() === "lt") return "<";
  const parts = inside.split("-");
  // `<C-->` is control and minus: the last part is the key, even when empty.
  const key = parts.length > 1 && parts.at(-1) === "" ? "-" : (parts.pop() ?? "");
  if (key === "-") parts.splice(-2, 2);
  const modifiers = new Set(parts.map((each) => ALIASES[each.toLowerCase()] ?? refuse(at, `${each}- is not a modifier`)));
  return canonical(modifiers, base(key, at));
}

/**
 * A key sequence as its keys, each one canonical, so `<cr>` and `<CR>` are
 * one key and `<leader>p` is the leader and then `p`.
 */
export function parseKeys(notation: string, leader = "<Space>"): readonly string[] {
  const keys: string[] = [];
  let i = 0;
  while (i < notation.length) {
    const close = notation[i] === "<" ? notation.indexOf(">", i + 2) : -1;
    if (close === -1) {
      keys.push(LITERAL[notation.charAt(i)] ?? notation.charAt(i));
      i += 1;
      continue;
    }
    const inside = notation.slice(i + 1, close);
    if (inside.toLowerCase() === "leader") keys.push(...parseKeys(leader, leader === "<leader>" ? "<Space>" : leader));
    else keys.push(bracketed(inside, notation));
    i = close + 1;
  }
  if (keys.length === 0) refuse(JSON.stringify(notation), "is no key at all");
  return keys;
}

/** What a person's `ui.keys` in `config.yaml` may say: a key per mode, and the leader. */
export interface KeyOverrides {
  readonly normal?: Readonly<Record<string, string>>;
  readonly insert?: Readonly<Record<string, string>>;
  readonly leader?: string;
}

interface Binding {
  readonly notation: string;
  readonly keys: readonly string[];
  readonly action: string;
}

export interface Keymap {
  readonly leader: string;
  /** Per mode, a person's bindings first, then the frame's. */
  readonly bindings: Readonly<Record<Mode, readonly Binding[]>>;
}

const MODES: readonly Mode[] = ["normal", "insert"];

const same = (a: readonly string[], b: readonly string[]): boolean => a.length === b.length && a.every((key, i) => key === b[i]);
const startsWith = (long: readonly string[], short: readonly string[]): boolean => short.every((key, i) => key === long[i]);

function bindingsOf(map: Readonly<Record<string, unknown>>, leader: string, actions: readonly string[], at: string): Binding[] {
  return Object.entries(map).map(([notation, action]) => {
    if (typeof action !== "string" || !actions.includes(action)) {
      refuse(`${at}.${notation}`, `${JSON.stringify(action)} is not an action the frame declares`);
    }
    return { notation, keys: parseKeys(notation, leader), action };
  });
}

/** Two bindings where one is the other, or begins it, cannot both be meant; nor can a count's digit begin one. */
function checkUnambiguous(mode: Mode, bindings: readonly Binding[]): void {
  for (const [i, one] of bindings.entries()) {
    if (mode === "normal" && /^[1-9]$/.test(one.keys[0] ?? "")) {
      refuse(`ui.keys.${mode}.${one.notation}`, "begins with a digit, which is a count");
    }
    for (const other of bindings.slice(i + 1)) {
      const clash = same(one.keys, other.keys)
        ? "is the same keys as"
        : startsWith(other.keys, one.keys) || startsWith(one.keys, other.keys)
          ? "begins, or is begun by,"
          : undefined;
      if (clash !== undefined) refuse(`ui.keys.${mode}.${one.notation}`, `${clash} ${other.notation}, so neither can be pressed for sure`);
    }
  }
}

/**
 * The frame's keymap with a person's remaps over it, checked the way boot
 * checks it: a remap to an action the frame does not declare, or two
 * bindings a keypress cannot tell apart, is refused, naming the key.
 *
 * A remapped key replaces the frame's binding of that same key; the frame's
 * other bindings stay, so `<C-n>` for `nav.next` leaves `j` working too.
 */
export function buildKeymap(frame: Frame, overrides: KeyOverrides = {}): Keymap {
  const leader = overrides.leader ?? frame.keys.leader;
  parseKeys(leader);
  const bindings = Object.fromEntries(
    MODES.map((mode) => {
      const mine = bindingsOf(overrides[mode] ?? {}, leader, frame.actions, `ui.keys.${mode}`);
      const theirs = bindingsOf(frame.keys[mode], leader, frame.actions, `keys.${mode}`).filter(
        (binding) => !mine.some((remap) => same(remap.keys, binding.keys)),
      );
      const all = [...mine, ...theirs];
      checkUnambiguous(mode, all);
      return [mode, all];
    }),
  ) as Record<Mode, Binding[]>;
  return { leader, bindings };
}

/** The keys that perform an action in a mode: a person's binding before the frame's. */
export function keysFor(keymap: Keymap, mode: Mode, action: string): readonly string[] | undefined {
  return keymap.bindings[mode].find((binding) => binding.action === action)?.keys;
}

/** What one key did: completed a binding, began one, or nothing. */
export type KeyResult =
  | { readonly kind: "action"; readonly action: string; readonly count: number }
  | { readonly kind: "pending" }
  | { readonly kind: "none" };

/**
 * Keys in, actions out, the way Neovim reads them: a sequence completes a
 * binding, a count before it in normal mode (`5j`) repeats it, and a key that
 * neither completes nor begins a binding clears what was pending.
 */
export class KeyReader {
  private pending: string[] = [];
  private count = "";
  private mode: Mode | undefined;

  constructor(private readonly keymap: Keymap) {}

  press(mode: Mode, key: string): KeyResult {
    // A sequence begun in one mode is not finished in another.
    if (mode !== this.mode) this.reset();
    this.mode = mode;
    if (mode === "normal" && this.pending.length === 0 && /^[0-9]$/.test(key) && (key !== "0" || this.count !== "")) {
      this.count += key;
      return { kind: "pending" };
    }
    const keys = [...this.pending, key];
    const bindings = this.keymap.bindings[mode];
    const done = bindings.find((binding) => same(binding.keys, keys));
    if (done !== undefined) {
      const count = this.count === "" ? 1 : Number(this.count);
      this.reset();
      return { kind: "action", action: done.action, count };
    }
    if (bindings.some((binding) => startsWith(binding.keys, keys))) {
      this.pending = keys;
      return { kind: "pending" };
    }
    this.reset();
    return { kind: "none" };
  }

  private reset(): void {
    this.pending = [];
    this.count = "";
  }
}

import type { Frame, Mode, Size } from "./frame.js";
import type { KeyOverrides } from "./keymap.js";
import type { Json } from "../json.js";
import type { Intent, Node } from "../tree.js";

/**
 * What a renderer measures in: a desktop window lays out in pixels, a
 * terminal in cells. Boxes are only ever compared relationally, so the two
 * compare the same way.
 */
export type Unit = "px" | "cell";

export interface Box {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

/**
 * What the harness, standing in for the server, hands a renderer: every
 * region of the frame with the tree for each thing it holds, and whether a
 * toggled region or an overlay is open. A renderer translates this and
 * decides nothing about it.
 */
export interface Scene {
  readonly mode: Mode;
  readonly regions: Readonly<Record<string, { readonly open: boolean; readonly holds: Readonly<Record<string, Node>> }>>;
}

/** One region as the renderer laid it out, read back from its own layout engine. */
export interface LaidRegion {
  readonly name: string;
  readonly box: Box;
  readonly holds: readonly { readonly name: string; readonly tree: Node }[];
}

export interface LaidSurface {
  readonly size: Size;
  readonly regions: readonly LaidRegion[];
}

/** Everything a renderer drew, per surface. */
export interface Laid {
  readonly surfaces: Readonly<Record<string, LaidSurface>>;
}

/** A mouse gesture on something drawn: a click on a row, a wheel over the list, a click on the panel's edge. */
export interface Pointer {
  readonly gesture: string;
  readonly on: string;
  readonly args: { readonly [key: string]: Json };
}

export interface Session {
  draw(scene: Scene): void;
  /** One key, in Neovim notation; what it made the renderer ask for. */
  press(key: string): readonly Intent[];
  pointer(gesture: Pointer): readonly Intent[];
  resize(size: Size): void;
  read(): Laid;
}

/**
 * A renderer as the conformance script drives it. It declares the surfaces
 * it draws, and is measured on exactly those.
 */
export interface ConformanceRenderer {
  readonly name: string;
  readonly unit: Unit;
  readonly surfaces: readonly string[];
  /** The window it opens at. */
  readonly size: Size;
  start(options: { readonly frame: Frame; readonly keys?: KeyOverrides }): Session;
}

/** A value that survives `JSON.stringify` and `JSON.parse` unchanged. */
export type Json = string | number | boolean | null | readonly Json[] | { readonly [key: string]: Json };

/**
 * Whether a value is JSON, all the way down.
 *
 * Stricter than `JSON.stringify`, which quietly drops a function and turns
 * `NaN` into `null`: either would reach a renderer as something other than
 * what the view said.
 */
export function isJson(value: unknown): value is Json {
  return jsonCopy(value) !== undefined;
}

/**
 * The value as JSON will send it, read once and frozen — or `undefined` when
 * it is not JSON. A check that reads a value and a send that reads it again
 * can disagree, through a getter or a mutation in between; keeping the copy
 * the check read is what makes what was checked what is sent.
 */
export function jsonCopy(value: unknown): Json | undefined {
  return copyOnPath(value, new Set());
}

/**
 * `path` holds the objects between the root and here, so a cycle is refused
 * rather than recursed into forever, while one value shared by two branches
 * is still JSON.
 */
function copyOnPath(value: unknown, path: Set<object>): Json | undefined {
  if (value === null || typeof value === "string" || typeof value === "boolean") return value;
  if (typeof value === "number") return Number.isFinite(value) ? value : undefined;
  if (typeof value !== "object" || path.has(value)) return undefined;
  // A `toJSON` hook is what `JSON.stringify` sends instead of the value itself.
  if (typeof (value as { toJSON?: unknown }).toJSON === "function") return undefined;
  if (!onlyWhatJsonSends(value)) return undefined;
  path.add(value);
  try {
    if (Array.isArray(value)) return copyArray(value, path);
    return isPlainObject(value) ? copyObject(value, path) : undefined;
  } finally {
    path.delete(value);
  }
}

/**
 * Every indexed slot, read the way `JSON.stringify` reads it — not through
 * the iterator, which may yield something else — and nothing when the array
 * carries keys besides its indexes, which JSON drops. A hole reads as
 * `undefined`, and is refused as one.
 */
function copyArray(value: readonly unknown[], path: Set<object>): Json | undefined {
  if (Object.keys(value).length !== value.length) return undefined;
  const items: Json[] = [];
  for (let i = 0; i < value.length; i++) {
    const item = copyOnPath(value[i], path);
    if (item === undefined) return undefined;
    items.push(item);
  }
  return Object.freeze(items);
}

function copyObject(value: Record<string, unknown>, path: Set<object>): Json | undefined {
  const copy: Record<string, Json> = {};
  for (const key of Object.keys(value)) {
    const item = copyOnPath(value[key], path);
    if (item === undefined) return undefined;
    // Defined rather than assigned, so a key named `__proto__` stays a key.
    Object.defineProperty(copy, key, { value: item, enumerable: true, writable: true, configurable: true });
  }
  return Object.freeze(copy);
}

/**
 * Whether every own property of an object is one `JSON.stringify` sends: a
 * non-enumerable one passes a check that reads it and is gone on arrival.
 * An array's own `length` is the one exception, and is not sent either.
 */
export function onlyWhatJsonSends(value: object): boolean {
  if (Object.getOwnPropertySymbols(value).length > 0) return false;
  const names = Object.getOwnPropertyNames(value).length;
  return names === Object.keys(value).length + (Array.isArray(value) ? 1 : 0);
}

/** Whether a value is an object literal's kind of object, not a date, a map or a class instance. */
export function isPlainObject(value: unknown): value is Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const prototype = Object.getPrototypeOf(value) as unknown;
  return prototype === Object.prototype || prototype === null;
}

/** Whether two JSON values are the same value, key order aside. */
export function sameJson(a: Json, b: Json): boolean {
  if (a === b) return true;
  if (typeof a !== "object" || typeof b !== "object" || a === null || b === null) return false;
  if (Array.isArray(a) || Array.isArray(b)) {
    return Array.isArray(a) && Array.isArray(b) && a.length === b.length && a.every((item, i) => sameJson(item, b[i] as Json));
  }
  const left = a as { readonly [key: string]: Json };
  const right = b as { readonly [key: string]: Json };
  const keys = Object.keys(left);
  return keys.length === Object.keys(right).length && keys.every((key) => Object.hasOwn(right, key) && sameJson(left[key] as Json, right[key] as Json));
}

// What a compiler in development mode imports. The same runtime: a view
// built in a test is the view built in a release.
export { jsx as jsxDEV, JSX } from "./jsx-runtime.js";

import { element, type Children, type Node } from "./tree.js";

/**
 * JSX, without React.
 *
 * Set as a package's `jsxImportSource`, this is what the compiler calls for
 * every tag, and what it returns is a `Node`: data, not something mounted.
 * A tag names a primitive, or a function of its props that returns one —
 * which is how a view is split into smaller views.
 */
type Component<P> = (props: P) => Node;

export function jsx<P extends object>(type: Component<P> | string, props: P, _key?: string): Node {
  if (typeof type === "function") return type(props);
  // A lowercase tag reaches here as a string, and is refused by name: there
  // is no intrinsic element, only the vocabulary.
  const { children, ...rest } = props as P & { children?: Children };
  return element(type, rest, children);
}

/** What the compiler calls for a tag with several children. The same thing: children are flattened either way. */
export function jsxs<P extends object>(type: Component<P> | string, props: P, key?: string): Node {
  return jsx(type, props, key);
}

// The JSX namespace is how the compiler checks a tag; it is types only.
// eslint-disable-next-line @typescript-eslint/no-namespace -- the compiler reads JSX from a namespace, there is no other spelling
export namespace JSX {
  export type Element = Node;
  // eslint-disable-next-line @typescript-eslint/no-empty-object-type -- no intrinsic elements: every tag is a primitive or a view
  export interface IntrinsicElements {}
  export interface ElementChildrenAttribute {
    children: object;
  }
}

import type { Json } from "./json.js";
import { element, type Children, type Intent, type Node } from "./tree.js";
import type { Primitive, TONES } from "./vocabulary.js";

type Tone = (typeof TONES)[number];

export interface Column {
  readonly label?: string;
  readonly width?: number;
  /** A column a row may leave blank: from the first one on, a text line is not padded past its last word. */
  readonly optional?: boolean;
}

export interface TimelineEntry {
  readonly at: string;
  readonly label: string;
}

export interface Transition {
  readonly from: string;
  readonly to: string;
}

interface Holds {
  readonly children?: Children;
}

export interface StackProps extends Holds { readonly gap?: number }
export interface RowProps extends Holds { readonly gap?: number }
export interface SectionProps extends Holds { readonly title?: string }
export interface TextProps extends Holds { readonly tone?: Tone }
export interface BadgeProps extends Holds { readonly tone?: Tone }
export interface ListProps extends Holds { readonly ordered?: boolean }
export interface TableProps { readonly columns: readonly Column[]; readonly rows: readonly (readonly string[])[] }
export type TabsProps = Holds;
export interface ButtonProps extends Holds { readonly intent: Intent }
export interface LinkProps extends Holds { readonly href: string }
export interface InputProps { readonly name: string; readonly value?: string; readonly placeholder?: string; readonly intent?: Intent }
export interface TimelineProps { readonly entries: readonly TimelineEntry[] }
/**
 * A workflow's states, and, when the workflow has one, the Mermaid diagram
 * they were read from. A renderer that draws in a webview hands `diagram` to
 * a Mermaid renderer; one that draws characters draws `states` and
 * `transitions`, which the server read out of the same text. Neither parses
 * Mermaid itself. A workflow without a diagram carries its states alone.
 */
export interface StateMachineProps {
  readonly states: readonly string[];
  readonly current?: string;
  readonly transitions?: readonly Transition[];
  readonly diagram?: string;
}
export interface LogProps { readonly lines: readonly string[] }
export interface CodeProps extends Holds { readonly language?: string }
export type DiffProps = Holds;
export type EmptyProps = Holds;

/** A primitive as a function a JSX tag can name. Calling it builds the node. */
function primitive<P extends object>(type: Primitive): (props: P) => Node {
  return (props) => {
    const { children, ...rest } = props as P & Holds;
    return element(type, rest as Record<string, Json | undefined>, children);
  };
}

export const Stack = primitive<StackProps>("Stack");
export const Row = primitive<RowProps>("Row");
export const Section = primitive<SectionProps>("Section");
export const Text = primitive<TextProps>("Text");
export const Badge = primitive<BadgeProps>("Badge");
export const List = primitive<ListProps>("List");
export const Table = primitive<TableProps>("Table");
export const Tabs = primitive<TabsProps>("Tabs");
export const Button = primitive<ButtonProps>("Button");
export const Link = primitive<LinkProps>("Link");
export const Input = primitive<InputProps>("Input");
export const Timeline = primitive<TimelineProps>("Timeline");
export const StateMachine = primitive<StateMachineProps>("StateMachine");
export const Log = primitive<LogProps>("Log");
export const Code = primitive<CodeProps>("Code");
export const Diff = primitive<DiffProps>("Diff");
export const Empty = primitive<EmptyProps>("Empty");

import type { Json } from "./json.js";
import type { Child, Node } from "./tree.js";
import type { Primitive } from "./vocabulary.js";

/**
 * The text renderer: a tree in, the text a terminal prints out.
 *
 * Deterministic on purpose — no clock, no width, no colour — so the same tree
 * is the same bytes every time, which is what makes it the snapshot a test
 * asserts and the first renderer a conformance script measures.
 */
export function renderText(tree: Child): string {
  return typeof tree === "string" ? tree : DRAW[tree.type](tree);
}

type Props = Node["props"];
type Draw = (node: Node) => string;

const text = (node: Node): string => node.children.map(renderText).join("");
const string = (props: Props, key: string): string | undefined => {
  const value = props[key];
  return typeof value === "string" ? value : undefined;
};
const number = (props: Props, key: string, otherwise: number): number => {
  const value = props[key];
  return typeof value === "number" ? value : otherwise;
};
const records = (props: Props, key: string): readonly { readonly [key: string]: Json }[] =>
  (props[key] ?? []) as readonly { readonly [key: string]: Json }[];

/** A child of a list, its first line after the marker and the rest under it. */
function item(marker: string, child: Child): string {
  const indent = " ".repeat(marker.length);
  return renderText(child).split("\n").map((line, i) => (i === 0 ? marker : indent) + line).join("\n");
}

interface Column {
  readonly label?: string;
  readonly width?: number;
  readonly optional?: boolean;
}

/**
 * One line of a table: each cell padded to its column's width, one space
 * between them. From the first optional column on, nothing is padded past
 * the last word, so a row that left those blank ends where its required
 * columns do — separator included, which is what keeps it in line.
 */
function tableLine(columns: readonly Column[], cells: readonly string[]): string {
  const padded = columns.map((column, i) => {
    const cell = cells[i] ?? "";
    return column.width === undefined ? cell : cell.padEnd(column.width);
  });
  const firstOptional = columns.findIndex((column) => column.optional);
  if (firstOptional === -1) return padded.join(" ");
  const tail = padded.slice(firstOptional).join(" ").trimEnd();
  return firstOptional === 0 ? tail : `${padded.slice(0, firstOptional).join(" ")} ${tail}`;
}

function table(node: Node): string {
  const columns = records(node.props, "columns") as readonly Column[];
  const rows = (node.props.rows ?? []) as readonly (readonly string[])[];
  const header = columns.some((column) => column.label !== undefined)
    ? [tableLine(columns, columns.map((column) => column.label ?? ""))]
    : [];
  return [...header, ...rows.map((row) => tableLine(columns, row))].join("\n");
}

/**
 * The states on one line, the current one marked, and then each declared
 * transition on a line of its own. Nothing between two states is drawn as an
 * edge unless the tree declared it: the order of `states` is not a path.
 */
function stateMachine(node: Node): string {
  const current = string(node.props, "current");
  const states = (node.props.states ?? []) as readonly string[];
  const line = states.map((state) => (state === current ? `[${state}]` : state)).join(" · ");
  const edges = records(node.props, "transitions").map((edge) => `${String(edge.from)} → ${String(edge.to)}`);
  return [line, ...edges].join("\n");
}

const DRAW: Readonly<Record<Primitive, Draw>> = {
  Stack: (node) => node.children.map(renderText).join("\n".repeat(number(node.props, "gap", 0) + 1)),
  Row: (node) => node.children.map(renderText).join(" ".repeat(number(node.props, "gap", 1))),
  Section: (node) => {
    const title = string(node.props, "title");
    return [...(title === undefined ? [] : [title]), ...node.children.map(renderText)].join("\n");
  },
  Text: text,
  Badge: (node) => `(${text(node)})`,
  List: (node) =>
    node.children.map((child, i) => item(node.props.ordered === true ? `${i + 1}. ` : "- ", child)).join("\n"),
  Table: table,
  Tabs: (node) => node.children.map(renderText).join("\n\n"),
  Button: (node) => `[${text(node)}]`,
  Link: (node) => {
    const href = string(node.props, "href") ?? "";
    const label = text(node);
    return label ? `${label} <${href}>` : href;
  },
  Input: (node) => {
    const value = string(node.props, "value");
    const placeholder = string(node.props, "placeholder");
    const shown = value ?? (placeholder === undefined ? "" : `<${placeholder}>`);
    return `${string(node.props, "name") ?? ""}: ${shown}`.trimEnd();
  },
  Timeline: (node) => records(node.props, "entries").map((entry) => `${String(entry.at)}  ${String(entry.label)}`).join("\n"),
  StateMachine: stateMachine,
  Log: (node) => ((node.props.lines ?? []) as readonly string[]).join("\n"),
  Code: text,
  Diff: text,
  Empty: text,
};

import { isPlainObject, jsonCopy, onlyWhatJsonSends, type Json } from "./json.js";
import { fitsPropType, PRIMITIVES, VOCABULARY, type Primitive } from "./vocabulary.js";

/**
 * One primitive in a view's tree.
 *
 * Plain data and nothing else, so a tree survives a socket, a file and a
 * phone, and a test compares it with `toEqual`.
 */
export interface Node {
  readonly type: Primitive;
  readonly props: { readonly [key: string]: Json };
  readonly children: readonly Child[];
}

export type Child = Node | string;

/**
 * What a button or an input asks amy to do: an action named, with arguments.
 *
 * Never a closure. A closure cannot cross a socket, and the thing that
 * performs the action is amy, not the renderer that drew the button.
 */
export interface Intent {
  readonly action: string;
  readonly args: { readonly [key: string]: Json };
}

/** What may appear between a primitive's tags: nested arrays, and holes a condition left. */
export type Children = Child | number | boolean | null | undefined | readonly Children[];

function refuse(at: string, said: string): never {
  throw new TypeError(`${at}: ${said}`);
}

function primitiveNamed(type: unknown, at: string): Primitive {
  if (typeof type === "string" && (PRIMITIVES as readonly string[]).includes(type)) return type as Primitive;
  return refuse(at, `${JSON.stringify(type)} is not a primitive. The vocabulary is ${PRIMITIVES.join(", ")}`);
}

/**
 * The props, checked against the primitive's spec, as a frozen copy of what
 * the check read: what a getter or a later mutation does to the original no
 * longer reaches the tree.
 */
function checkedProps(type: Primitive, props: Readonly<Record<string, unknown>>, at: string): Node["props"] {
  const spec = VOCABULARY[type].props;
  const copy: Record<string, Json> = {};
  for (const [key, value] of Object.entries(props)) {
    // Own keys only: `constructor` or `toString` would otherwise find a member of the spec object.
    const prop = Object.hasOwn(spec, key) ? spec[key] : undefined;
    if (!prop) return refuse(at, `${type} has no property \`${key}\``);
    const read = jsonCopy(value);
    if (read === undefined) return refuse(at, `${type}.${key} is not a JSON value`);
    if (!fitsPropType(prop.type, read)) return refuse(at, `${type}.${key} is not of type ${prop.type}`);
    copy[key] = read;
  }
  for (const [key, prop] of Object.entries(spec)) {
    if (prop.required && !Object.hasOwn(copy, key)) refuse(at, `${type} needs \`${key}\``);
  }
  if (type === "Table") checkRows(copy, at);
  return Object.freeze(copy);
}

/** A row may leave cells blank, but no cell may fall outside every column: no renderer would draw it. */
function checkRows(props: Readonly<Record<string, Json>>, at: string): void {
  const columns = (props.columns as readonly Json[]).length;
  (props.rows as readonly (readonly Json[])[]).forEach((row, i) => {
    if (row.length > columns) refuse(at, `Table row ${i} has ${row.length} cells for ${columns} columns`);
  });
}

function checkChildren(type: Primitive, children: readonly Child[], at: string): void {
  const kind = VOCABULARY[type].children;
  if (kind === "none" && children.length > 0) refuse(at, `${type} holds nothing`);
  if (kind === "text" && children.some((child) => typeof child !== "string")) refuse(at, `${type} holds text only`);
  if (type === "Tabs" && children.some((child) => typeof child === "string" || child.type !== "Section")) {
    refuse(at, "Tabs holds a Section per tab");
  }
}

function flatten(children: Children, into: Child[]): Child[] {
  if (children === null || children === undefined || typeof children === "boolean") return into;
  if (typeof children === "number") into.push(String(children));
  else if (typeof children === "string" || !Array.isArray(children)) into.push(children as Child);
  else for (const child of children as readonly Children[]) flatten(child, into);
  return into;
}

/**
 * Nodes this module built or checked, so a tree built tag by tag is checked
 * once, not once per level. Every one of them is frozen, so none can change
 * after it was checked.
 */
const checked = new WeakSet<Node>();

function remember(type: Primitive, props: Node["props"], children: Child[]): Node {
  const node: Node = Object.freeze({ type, props, children: Object.freeze(children) });
  checked.add(node);
  return node;
}

/** A child built anywhere but here — by hand, or parsed — is checked the way `validate` would check it. */
function trusted(child: Child, at: string): Child {
  return typeof child === "string" || checked.has(child) ? child : validateAt(child, at);
}

/**
 * One primitive, built and checked.
 *
 * Refuses a name outside the vocabulary, a property the primitive does not
 * declare, and any value that is not JSON — a function included — naming
 * the one it refused. A property set to `undefined` is left out, which is
 * how a view writes an optional one.
 */
export function element(type: string, props: Readonly<Record<string, unknown>> = {}, children: Children = []): Node {
  const primitive = primitiveNamed(type, "view");
  const defined = Object.fromEntries(Object.entries(props).filter(([, value]) => value !== undefined));
  const read = checkedProps(primitive, defined, primitive);
  const flat = flatten(children, []).map((child, i) => trusted(child, `${primitive}/${i}`));
  checkChildren(primitive, flat, primitive);
  return remember(primitive, read, flat);
}

/** `above` holds the nodes between the root and here, so a node that holds itself is refused, not recursed into forever. */
function validateAt(value: unknown, at: string, above: Set<object> = new Set()): Child {
  if (typeof value === "string") return value;
  if (typeof value !== "object" || value === null || Array.isArray(value)) return refuse(at, "is not a primitive or text");
  if (above.has(value)) return refuse(at, "holds itself, which no tree can");
  if (!onlyWhatJsonSends(value)) return refuse(at, "carries a property JSON would not send");
  const { type, props, children, ...rest } = value as Record<string, unknown>;
  const extra = Object.keys(rest);
  if (extra.length > 0) refuse(at, `carries ${extra.map((key) => `\`${key}\``).join(", ")}, which no primitive has`);
  const primitive = primitiveNamed(type, at);
  if (!isPlainObject(props)) return refuse(at, `${primitive} has no props object`);
  // The container too: a hidden `toJSON` on it would send something else in its place.
  const container = jsonCopy(props);
  if (container === undefined) return refuse(at, `${primitive} props are not a JSON value`);
  if (!Array.isArray(children)) return refuse(at, `${primitive} has no children list`);
  const valid = checkedProps(primitive, container as Record<string, Json>, at);
  // Each slot read once by index: a hole is refused, and no iterator or getter answers twice.
  const list: Child[] = [];
  above.add(value);
  for (let i = 0; i < children.length; i++) list.push(validateAt(children[i], `${at}/${i}`, above));
  above.delete(value);
  checkChildren(primitive, list, at);
  return remember(primitive, valid, list);
}

/**
 * A tree that arrived as data — from a socket, a file, a plugin — checked
 * against the vocabulary before anything draws it.
 *
 * A renderer draws what this returns and nothing else, so a primitive the
 * vocabulary does not have is refused here, named, with where it was.
 */
export function validate(value: unknown): Node {
  const tree = validateAt(value, "root");
  if (typeof tree === "string") return refuse("root", "is text, not a primitive");
  return tree;
}

import { isJson, type Json } from "./json.js";

/**
 * Every primitive a view may use, and nothing else.
 *
 * Semantic rather than visual: `StateMachine` says what the thing is, so a
 * terminal can draw it as a line and a browser as a graph. Short on purpose,
 * for the reason the config schema has five types — every name here is one
 * every renderer has to draw.
 */
export const PRIMITIVES = [
  "Stack",
  "Row",
  "Section",
  "Text",
  "Badge",
  "List",
  "Table",
  "Tabs",
  "Button",
  "Link",
  "Input",
  "Timeline",
  "StateMachine",
  "Log",
  "Code",
  "Diff",
  "Empty",
] as const;

export type Primitive = (typeof PRIMITIVES)[number];

/** The kinds of value a property may hold. Each one is JSON, and has a schema. */
export type PropType =
  | "string"
  | "count"
  | "boolean"
  | "tone"
  | "strings"
  | "intent"
  | "columns"
  | "rows"
  | "entries"
  | "transitions";

export interface PropSpec {
  readonly type: PropType;
  readonly required?: true;
}

/** What a primitive holds inside it: nothing, text only, or other primitives. */
export type ChildrenKind = "none" | "text" | "nodes";

export interface PrimitiveSpec {
  readonly props: Readonly<Record<string, PropSpec>>;
  readonly children: ChildrenKind;
}

/** How loudly a renderer should draw something. The meaning is the renderer's. */
export const TONES = ["neutral", "muted", "success", "warning", "danger"] as const;

const optional = (type: PropType): PropSpec => ({ type });
const required = (type: PropType): PropSpec => ({ type, required: true });

export const VOCABULARY: Readonly<Record<Primitive, PrimitiveSpec>> = {
  Stack: { props: { gap: optional("count") }, children: "nodes" },
  Row: { props: { gap: optional("count") }, children: "nodes" },
  Section: { props: { title: optional("string") }, children: "nodes" },
  Text: { props: { tone: optional("tone") }, children: "text" },
  Badge: { props: { tone: optional("tone") }, children: "text" },
  List: { props: { ordered: optional("boolean") }, children: "nodes" },
  Table: { props: { columns: required("columns"), rows: required("rows") }, children: "none" },
  Tabs: { props: {}, children: "nodes" },
  Button: { props: { intent: required("intent") }, children: "text" },
  Link: { props: { href: required("string") }, children: "text" },
  Input: {
    props: { name: required("string"), value: optional("string"), placeholder: optional("string"), intent: optional("intent") },
    children: "none",
  },
  Timeline: { props: { entries: required("entries") }, children: "none" },
  StateMachine: {
    props: { states: required("strings"), current: optional("string"), transitions: optional("transitions"), diagram: optional("string") },
    children: "none",
  },
  Log: { props: { lines: required("strings") }, children: "none" },
  Code: { props: { language: optional("string") }, children: "text" },
  Diff: { props: {}, children: "text" },
  Empty: { props: {}, children: "text" },
};

type Record_ = { readonly [key: string]: Json };

const isRecord = (value: Json): value is Record_ => typeof value === "object" && value !== null && !Array.isArray(value);
const isString = (value: unknown): value is string => typeof value === "string";
const isStrings = (value: Json): boolean => Array.isArray(value) && value.every(isString);
const listOf = (value: Json, each: (item: Record_) => boolean): boolean =>
  Array.isArray(value) && value.every((item: Json) => isRecord(item) && each(item));
const optionalOf = (value: Json | undefined, check: (value: Json) => boolean): boolean => value === undefined || check(value);
const keysWithin = (item: Record_, allowed: readonly string[]): boolean => Object.keys(item).every((key) => allowed.includes(key));

/** Whether a value is an intent: an action named, with JSON arguments. */
export function isIntent(value: Json): boolean {
  return isRecord(value) && keysWithin(value, ["action", "args"]) && isString(value.action) && isRecord(value.args ?? null);
}

const isCount = (value: Json): boolean => typeof value === "number" && Number.isInteger(value) && value >= 0;

const CHECKS: Readonly<Record<PropType, (value: Json) => boolean>> = {
  string: isString,
  count: isCount,
  boolean: (value) => typeof value === "boolean",
  tone: (value) => isString(value) && (TONES as readonly string[]).includes(value),
  strings: isStrings,
  intent: isIntent,
  columns: (value) =>
    listOf(value, (column) =>
      keysWithin(column, ["label", "width", "optional"]) &&
      optionalOf(column.label, isString) &&
      optionalOf(column.width, isCount) &&
      optionalOf(column.optional, (flag) => typeof flag === "boolean")),
  rows: (value) => Array.isArray(value) && value.every(isStrings),
  entries: (value) => listOf(value, (entry) => keysWithin(entry, ["at", "label"]) && isString(entry.at) && isString(entry.label)),
  transitions: (value) => listOf(value, (edge) => keysWithin(edge, ["from", "to"]) && isString(edge.from) && isString(edge.to)),
};

/** Whether a value is one a property of this type may hold. */
export function fitsPropType(type: PropType, value: unknown): boolean {
  return isJson(value) && CHECKS[type](value);
}

const STRING = { type: "string" } as const;
const STRINGS = { type: "array", items: STRING } as const;
const COUNT = { type: "integer", minimum: 0 } as const;
const closed = (properties: Record<string, Json>, requiredKeys: readonly string[]): Json => ({
  type: "object",
  properties,
  required: [...requiredKeys],
  additionalProperties: false,
});

/** The JSON Schema of each property type, which is what a catalogue publishes. */
export const PROP_SCHEMAS: Readonly<Record<PropType, Json>> = {
  string: STRING,
  count: COUNT,
  boolean: { type: "boolean" },
  tone: { type: "string", enum: [...TONES] },
  strings: STRINGS,
  intent: closed({ action: STRING, args: { type: "object" } }, ["action", "args"]),
  columns: {
    type: "array",
    items: closed({ label: STRING, width: COUNT, optional: { type: "boolean" } }, []),
  },
  rows: { type: "array", items: STRINGS },
  entries: { type: "array", items: closed({ at: STRING, label: STRING }, ["at", "label"]) },
  transitions: { type: "array", items: closed({ from: STRING, to: STRING }, ["from", "to"]) },
};

/** One component of a catalogue: a primitive's name, its props as JSON Schema, and what it holds. */
export interface CatalogueComponent {
  readonly name: Primitive;
  readonly props: Json;
  readonly children: ChildrenKind;
}

/**
 * The vocabulary as a component catalogue, one component per primitive.
 *
 * What a later plugin hands to a declarative UI standard once one settles:
 * every property is described by JSON Schema alone, so nothing here needs a
 * feature such a catalogue cannot express.
 */
export function catalogue(): readonly CatalogueComponent[] {
  return PRIMITIVES.map((name) => {
    const spec = VOCABULARY[name];
    const entries = Object.entries(spec.props);
    return {
      name,
      props: closed(
        Object.fromEntries(entries.map(([key, prop]) => [key, PROP_SCHEMAS[prop.type]])),
        entries.filter(([, prop]) => prop.required).map(([key]) => key),
      ),
      children: spec.children,
    };
  });
}
